import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls} from './pathways-views.js?v=20261110-en1';
import {heatmapSVG,quantumCurveSVG} from './quantum-plots.js?v=20261110-en1';
export {esc,num,table,notes,sources,readControls};
const val=x=>typeof x==='boolean'?(x?"Yes":"No"):typeof x==='number'?num(x):x==null?"undefined":String(x);
const clean=r=>{const c=structuredClone(r);delete c.learningEvidence;return c;};
const anchors=new Map();
export function controlsHTML(m,v){const keys={statistics:[],defects:['separation','loopX','loopY','radius'],reciprocity:['field','magnetization','cross']}[m.id];return baseControls({...m,fields:m.fields.map(f=>f.type==='number'?{...f,step:'any'}:f)},v)+(keys.length?`<details><summary>Continuous adjustment parameters</summary>${m.fields.filter(f=>keys.includes(f.key)).map(f=>`<label>${esc(f.label)}<input type="range" data-pr-control="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${v[f.key]}"></label>`).join('')}<p>Click Calculate after modification; click or drag the loop center in the defect map.</p></details>`:'');}
const matrix=m=>heatmapSVG(m[0].map((_,i)=>i),m.map((_,i)=>i),m,{title:"matrix or vector (real part)",signed:true,xLabel:"column",yLabel:"OK"});
export function plotHTML(p){
 if(p.kind==='response')return `<div class="cn-pair-grid"><div><h4>original configuration L</h4>${matrix(p.matrix)}</div><div><h4>reverse configuration L</h4>${matrix(p.reversed)}</div></div>${table(["Quantity","component 1","component 2"],[["Conjugate force",...p.force.map(num)],["response stream",...p.flux.map(num)]])}${table(["decomposition","line 1","line 2"],[["Symmetric dissipation part",...p.symmetric.map(x=>x.map(num).join(', '))],["antisymmetric part",...p.antisymmetric.map(x=>x.map(num).join(', '))]])}`;
 if(p.kind==='ising')return `<svg viewBox="0 0 600 300" role="img" aria-label="Continuous zero-crossing diagram of Ising domain wall"><path d="M40 150H560M300 25V270" stroke="#91a69b"/><polyline points="${p.x.map((x,i)=>`${300+65*x},${150-100*p.values[i]}`).join(' ')}" fill="none" stroke="#237c66" stroke-width="4"/><text x="45" y="280">x = −4</text><text x="480" y="280">x = 4</text><text x="320" y="35">order parameter</text></svg>`;
 if(p.kind==='texture'){const xy=([x,y])=>[300+75*x,265-75*y];return `<svg id="cn-texture" viewBox="0 0 600 530" role="img" aria-label="Direction field and closed loop, you can click or drag to change the center of the loop; you can also use the parameter input box"><rect x="65" y="30" width="470" height="470" fill="#f2f7f3"/>${p.field.map(([x,y,u,v])=>{const [a,b]=xy([x,y]),dx=10*u,dy=-10*v;return `<line x1="${a-dx}" y1="${b-dy}" x2="${a+dx}" y2="${b+dy}" stroke="#397c68" stroke-width="2"/>${p.headless?'':`<circle cx="${a+dx}" cy="${b+dy}" r="2.8" fill="#397c68"/>`}`;}).join('')}<polyline points="${p.path.map(q=>xy(q).join(',')).join(' ')}" fill="none" stroke="#b87631" stroke-width="4"/>${p.cores.map(([x,y,q])=>{const [a,b]=xy([x,y]);return `<circle cx="${a}" cy="${b}" r="9" fill="${q>0?'#b14b40':'#4464a1'}"/><text x="${a+12}" y="${b-10}">${q>0?'+':'−'}</text>`;}).join('')}<text x="65" y="525">−3 ≤ x,y ≤ 3 · Orange is the sampling loop</text></svg>`;}
 if(p.kind==='amplitudes')return `<svg viewBox="0 0 680 330" role="img" aria-label="original state and amplitude after operation, green original state, ocher after operation"><path d="M35 160H650" stroke="#a1b6aa"/>${p.labels.map((s,i)=>{const x=60+i*580/p.labels.length;return `<line x1="${x}" x2="${x}" y1="160" y2="${160-110*p.values[i]}" stroke="#237c66" stroke-width="9"/><line x1="${x+12}" x2="${x+12}" y1="160" y2="${160-110*p.after[i]}" stroke="#b87631" stroke-width="9"/><text x="${x}" y="300" text-anchor="middle">${esc(s)}</text>`;}).join('')}<text x="40" y="24">Amplitude · Green original state / After ocher operation</text></svg>`;
 return '';
}
const tasks={projector:"Normalization coefficient c of non-zero antisymmetric projection",young:"Y²=3Y: non-zero idempotent normalization coefficient c",exchange:"Symmetric orbital × total exchange sign of singlet state",winding:"The director rotates through π: Δθ/(2π)",onsager:"L12=a+b(B+M), L21 of two even variables",commutator:"Coefficient of σy in [σz,hσx]"};
export function resultHTML(module,r){return `<div class="cn-summary">${table(["The result of this time","Numeric/Diagnostic"],r.summary.map(s=>[s.label,val(s.value)]))}</div><section class="ct-panel"><h3>interactive demonstration</h3>${plotHTML(r.plot)}</section><section class="ct-panel"><h3>Derivation and operation playback</h3><label>View steps<input id="cn-frame" type="range" min="0" max="${r.replay.length-1}" value="0" step="1"></label><div id="cn-frame-result"></div></section>${r.tables.map(t=>`<section class="ct-panel"><h3>${esc(t.title)}</h3>${table(t.headers,t.rows.map(row=>row.map(val)))}</section>`).join('')}<section class="ct-panel"><h3>Formulas and Assumptions</h3>${r.formulas.map(f=>`<div class="obs-formula">${esc(f)}</div>`).join('')}${notes(r.notes)}</section><section class="ct-panel"><h3>Counterexample challenge</h3><p>${esc(r.challenge.question)}</p>${r.challenge.choices.map((s,i)=>`<button type="button" class="secondary" data-cn-challenge="${i}">${esc(s)}</button>`).join('')}<p id="cn-challenge-feedback" role="status"></p></section><section class="ct-panel"><h3>Symbolic step scoring with assumptions</h3><label>Select task<select id="cn-task">${r.symbolicTasks.map(t=>`<option value="${t}">${tasks[t]}</option>`).join('')}</select></label><p>Integers, parentheses, + − * / and a b B M h I are allowed; use 1/2 to represent fractions and I to represent imaginary units. Only verify the identity specified in this question.</p><label>your exact expression<input id="cn-answer" maxlength="180" placeholder="For example 1/2" autocomplete="off"></label><button id="cn-grade" type="button" class="secondary">Check this step</button><div id="cn-grade-result" role="status"></div></section><section class="ct-panel"><h3>Hamiltonian-state-measurement three-layer check</h3><p>Independent two-level diagnostic bench: H=hₓσₓ+h_zσ_z, ρ=(I+r n·σ)/2, probe in xz plane. It does not automatically replace the model above.</p><div class="cn-audit-controls"><label>Operation<select id="cn-operation"><option value="z">σz unitary transformation</option><option value="time">Spin 1/2 time reversal</option></select></label>${[['hx','hₓ',1,-2,2],['hz','h_z',0,-2,2],['stateAngle',"State direction angle (degrees)",0,-180,180],['probeAngle',"Probe angle (degrees)",90,-180,180],['polarization',"Bloch vector length r",1,0,1]].map(([id,t,v,min,max])=>`<label>${t}<input id="cn-${id}" type="number" value="${v}" min="${min}" max="${max}" step="any"></label>`).join('')}</div><button id="cn-audit" type="button" class="secondary">Check three levels of symmetry separately</button><div id="cn-audit-result" role="status"></div></section><section class="ct-panel"><h3>Paired experiments and evidence reporting</h3><p>First fix the calculation as A, and then modify the parameters to get B. Complete input, results, and your interpretations are saved; records are not automatically published.</p><div class="obs-links"><button id="cn-pin" type="button" class="secondary">Fix this result to A</button><button id="cn-compare" type="button" class="secondary">Compare with A and save evidence</button><button id="cn-clear" type="button" class="secondary">Clear A</button></div><label>Explanation for comparison of this group<textarea id="cn-explanation" rows="3" maxlength="6000" placeholder="What's reversed? Which assumptions hold? What conclusions do the numbers support?"></textarea></label><div id="cn-comparison" role="status"></div></section>`;}
export function bindResult(module,r,root,{runGrade,runAudit,input,isCurrent,onEvidence}){
 const $=s=>root.querySelector(s);let active=true,grading=0,auditing=0;
 const valid=()=>active&&isCurrent();
 const frame=()=>{const f=r.replay[+$('#cn-frame').value];$('#cn-frame-result').innerHTML=`<h4>${esc(f.title)}</h4><p>${esc(f.text)}</p>${f.matrix?matrix(f.matrix):''}`;};$('#cn-frame').oninput=frame;frame();
 const svg=$('#cn-texture');if(svg){svg.onpointerdown=e=>{svg.setPointerCapture?.(e.pointerId);};svg.onpointerup=e=>{const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const local=point.matrixTransform(svg.getScreenCTM().inverse());const x=Math.max(-3,Math.min(3,(local.x-300)/75)),y=Math.max(-3,Math.min(3,(265-local.y)/75));$('#pw-loopX').value=x.toFixed(3);$('#pw-loopY').value=y.toFixed(3);$('#pw-form').oninput({target:$('#pw-loopX')});$('#pw-form').onsubmit({preventDefault(){}});};}
 root.querySelectorAll('[data-cn-challenge]').forEach(b=>b.onclick=()=>{const answer=+b.dataset.cnChallenge,correct=answer===r.challenge.answer;$('#cn-challenge-feedback').textContent=(correct?'✓ ':"Think again:")+r.challenge.explanation;onEvidence('counterexample',{question:r.challenge.question,choice:r.challenge.choices[answer],correct,explanation:r.challenge.explanation});});
 const invalidateGrade=()=>{grading++;$('#cn-grade').disabled=false;$('#cn-grade-result').textContent="The answer has changed, please check again.";onEvidence('symbolic',null);};$('#cn-task').onchange=invalidateGrade;$('#cn-answer').oninput=invalidateGrade;
 $('#cn-grade').onclick=async()=>{const id=++grading,payload={task:$('#cn-task').value,answer:$('#cn-answer').value};$('#cn-grade').disabled=true;try{const g=await runGrade(payload);if(!valid()||id!==grading)return;$('#cn-grade-result').innerHTML=`<p>${g.correct?"✓ The identity holds":"Not equal yet"} · ${esc(g.prompt)}</p><p>Difference:${esc(g.difference)}</p><p>${esc(g.hint)}</p>`;onEvidence('symbolic',{input:payload,result:g});}catch(e){if(valid()&&id===grading)$('#cn-grade-result').textContent=e.message;}finally{if(valid()&&id===grading)$('#cn-grade').disabled=false;}};
 const auditKeys=['hx','hz','stateAngle','probeAngle','polarization','operation'];
 for(const key of auditKeys)$('#cn-'+key).oninput=()=>{auditing++;$('#cn-audit').disabled=false;$('#cn-audit-result').textContent="The diagnostic parameters have changed, please recheck.";onEvidence('audit',null);};
 $('#cn-audit').onclick=async()=>{const id=++auditing,payload=Object.fromEntries(auditKeys.map(k=>[k,k==='operation'?$('#cn-'+k).value:Number($('#cn-'+k).value)]));$('#cn-audit').disabled=true;try{const a=await runAudit(payload);if(!valid()||id!==auditing)return;$('#cn-audit-result').innerHTML=table(["examine","Residual/Result"],[["Operation",a.operation],["Model symmetry residuals",num(a.hamiltonian)],["State symmetry residuals",num(a.state)],["Probe symmetry residuals",num(a.probe)],["Probe is odd",val(a.probeOdd)],["expected value",num(a.expectation)],["This symmetry is forced to zero",val(a.forcedZero)]])+`<p>${esc(a.note)}</p>`;onEvidence('audit',{input:payload,result:a});}catch(e){if(valid()&&id===auditing)$('#cn-audit-result').textContent=e.message;}finally{if(valid()&&id===auditing)$('#cn-audit').disabled=false;}};
 const status=()=>{$('#cn-comparison').textContent=anchors.has(module)?"A has been fixed, and B can be calculated after modifying the main parameters.":"A has not been fixed yet.";};status();
 $('#cn-pin').onclick=()=>{anchors.set(module,{input:structuredClone(input),result:clean(r),created:new Date().toISOString()});onEvidence('comparison',null);status();};
 $('#cn-clear').onclick=()=>{anchors.delete(module);onEvidence('comparison',null);status();};
 const compare=()=>{const A=anchors.get(module);if(!A){status();return;}const B={input:structuredClone(input),result:clean(r),created:new Date().toISOString()},explanation=$('#cn-explanation').value;onEvidence('comparison',{A,B,explanation});$('#cn-comparison').innerHTML=table(["Quantity",'A','B'],r.summary.map(s=>[s.label,val(A.result.summary.find(x=>x.label===s.label)?.value),val(s.value)]))+`<p>The complete A/B parameters and results are attached to this calculation and can be exported to JSON or included in the materials project. explain${explanation.trim()?"saved":"Not filled in yet"}。</p>`;};$('#cn-compare').onclick=compare;$('#cn-explanation').oninput=()=>{onEvidence('comparison',null);$('#cn-comparison').textContent="The explanation has been modified, please click Compare again to save.";};
 return ()=>{active=false;grading++;auditing++;};
}
